module radix2_div (
    input wire clk,
    input wire rst,
    input wire [7:0] dividend,
    input wire [7:0] divisor,
    input wire sign,
    input wire opn_valid,
    output reg res_valid,
    input wire res_ready,
    output wire [15:0] result
);

reg [7:0] dividend_reg;
reg [7:0] divisor_reg;
reg [8:0] neg_divisor;
reg [15:0] sr;
reg [3:0] cnt;
reg start_cnt;
reg res_valid_reg;
wire [9:0] sub_result;
wire carry_out;
wire [8:0] mux_out;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        dividend_reg <= 8'd0;
        divisor_reg <= 8'd0;
        neg_divisor <= 9'd0;
        sr <= 16'd0;
        cnt <= 4'd0;
        start_cnt <= 1'b0;
        res_valid_reg <= 1'b0;
    end else begin
        if (opn_valid && !res_valid_reg) begin
            dividend_reg <= dividend;
            divisor_reg <= divisor;

            sr[15:8] <= {1'b0, dividend};
            sr[7:0] <= 8'd0;

            neg_divisor <= ~{1'b0, divisor} + 1;

            cnt <= 4'd1;
            start_cnt <= 1'b1;
        end else if (start_cnt) begin
            if (&cnt[3]) begin
                sr[15:8] <= mux_out;
                sr[7:0] <= sub_result[7:0];

                cnt <= 4'd0;
                start_cnt <= 1'b0;
            end else begin
                cnt <= cnt + 1;
                sr <= {mux_out, sr[7:1]};
            end
        end

        res_valid_reg <= rst ? 1'b0 : (&cnt || res_valid_reg) ? 1'b1 : ((res_valid_reg && res_valid) ? 1'b0 : res_valid_reg);
    end
end

assign sub_result = sr[15:8] + neg_divisor;
assign mux_out = sub_result[9] ? sr[15:8] : sub_result[8:0];
assign result = sr;
assign res_valid = res_valid_reg;
endmodule
